import React from "react";

import { Link } from "react-router-dom";

function toPersianDigits(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  const digits = "۰۱۲۳۴۵۶۷۸۹";

  return String(value).replace(
    /\d/g,
    (digit) => digits[Number(digit)]
  );
}

function getPersianMonthName(month) {
  const months = [
    "فروردین",
    "اردیبهشت",
    "خرداد",
    "تیر",
    "مرداد",
    "شهریور",
    "مهر",
    "آبان",
    "آذر",
    "دی",
    "بهمن",
    "اسفند",
  ];

  return months[month - 1] || "";
}

function getMonthLabel(dateString) {
  if (!dateString) {
    return "";
  }

  let value = String(dateString).trim();

  if (!value) {
    return "";
  }

  if (value.includes("T")) {
    value = value.split("T")[0];
  }

  value = value.replace(/\//g, "-");

  const parts = value.split("-");

  if (parts.length !== 3) {
    return "";
  }

  const year = Number(parts[0]);
  const month = Number(parts[1]);
  const day = Number(parts[2]);

  if (
    !year ||
    !month ||
    !day
  ) {
    return "";
  }

  try {
    // تاریخ شمسی
    if (year < 1700) {
      return `${toPersianDigits(
        year
      )} ${getPersianMonthName(month)}`;
    }

    // تاریخ میلادی
    const date = new Date(
      year,
      month - 1,
      day
    );

    return new Intl.DateTimeFormat(
      "fa-IR-u-ca-persian",
      {
        year: "numeric",
        month: "long",
      }
    ).format(date);
  } catch (error) {
    console.error(
      "MONTH FORMAT ERROR:",
      error
    );

    return "";
  }
}

class RequestRecords extends React.Component {
  // =========================================================
  // تاریخ رکورد
  // =========================================================

  getRecordDate = (record) => {
    return (
      record.original?.time ||
      record.original?.date ||
      record.original?.created_at ||
      record.date ||
      ""
    );
  };

  // =========================================================
  // هدر ماه
  // فقط برای List
  // =========================================================

  renderMonthHeader = (month) => {
    if (!month) {
      return null;
    }

    return (
      <div className="text-center small text-muted py-2 bg-light border-bottom">
        {month}
      </div>
    );
  };

  // =========================================================
  // Header جدول
  // Sticky نیست
  // چون Search + Tabs + Toolbar در RequestsPage
  // به صورت Sticky قرار گرفته‌اند
  // =========================================================

  renderListHeader = () => {
    return (
      <div
        className="d-grid text-center align-items-center py-3"
        style={{
          gridTemplateColumns:
            "1.2fr 1.2fr 1.2fr 1.2fr",

          backgroundColor: "#f5f5f5",

          color: "#4e3c9b",

          fontSize: "14px",

          minHeight: "68px",

          borderBottom:
            "1px solid #eeeeee",
        }}
      >
        <div>
          نام مشتری
        </div>

        <div>
          نوع دستگاه
        </div>

        <div>
          ایراد دستگاه
        </div>

        <div>
          برند دستگاه
        </div>
      </div>
    );
  };

  // =========================================================
  // List
  // =========================================================

  renderList = () => {
    const { records } = this.props;

    if (!records.length) {
      return this.renderEmpty();
    }

    let lastMonth = "";

    return (
      <div
        className="bg-white rounded-4"
        style={{
          border:
            "1px solid #f2f2f2",

          animation:
            "recordsFade .4s ease",
        }}
      >
        {/* Header */}

        {this.renderListHeader()}

        {/* Records */}

        <div>
          {records.map(
            (record, index) => {
              const month =
                getMonthLabel(
                  this.getRecordDate(
                    record
                  )
                );

              const showMonth =
                month &&
                month !== lastMonth;

              lastMonth = month;

              return (
                <React.Fragment
                  key={record.id}
                >
                  {showMonth &&
                    this.renderMonthHeader(
                      month
                    )}

                  <Link
                    to={`/request-details/${record.id}`}
                    className="d-block text-decoration-none text-dark"
                  >
                    <div
                      className="d-grid text-center align-items-center"
                      style={{
                        gridTemplateColumns:
                          "1.2fr 1.2fr 1.2fr 1.2fr",

                        minHeight:
                          "78px",

                        borderBottom:
                          index !==
                          records.length -
                            1
                            ? "1px solid #f4f4f4"
                            : "none",

                        fontSize:
                          "14px",

                        transition:
                          "background .25s ease",
                      }}
                    >
                      <div>
                        {
                          record.customerName
                        }
                      </div>

                      <div>
                        {
                          record.deviceType
                        }
                      </div>

                      <div>
                        {
                          record.problem
                        }
                      </div>

                      <div>
                        {
                          record.deviceBrand
                        }
                      </div>
                    </div>
                  </Link>
                </React.Fragment>
              );
            }
          )}
        </div>
      </div>
    );
  };

  // =========================================================
  // Card
  // بدون ماه‌بندی
  // =========================================================

  renderCard = (
    record,
    index
  ) => {
    return (
      <div
        key={record.id}
        className="bg-white rounded-4 p-3 h-100"
        style={{
          border:
            "1px solid #eeeeee",

          boxShadow:
            "0 2px 6px rgba(0,0,0,.08)",

          animation:
            `cardFade .4s ease ${
              index * 0.06
            }s both`,

          transition:
            "transform .25s ease, box-shadow .25s ease",
        }}
      >
        {/* Technician */}

        <div className="d-flex justify-content-between align-items-center mb-3">
          <strong
            className="fw-semibold"
            style={{
              fontSize: "14px",
            }}
          >
            تعمیرکار
          </strong>

          <span
            style={{
              fontSize: "14px",
            }}
          >
            {record.technician}
          </span>
        </div>

        {/* Device */}

        <div className="d-flex justify-content-between align-items-center mb-3">
          <strong
            className="fw-semibold"
            style={{
              fontSize: "14px",
            }}
          >
            نوع دستگاه
          </strong>

          <span
            style={{
              fontSize: "14px",
            }}
          >
            {record.deviceType}
          </span>
        </div>

        {/* Problem */}

        <div className="d-flex justify-content-between align-items-center mb-3">
          <strong
            className="fw-semibold"
            style={{
              fontSize: "14px",
            }}
          >
            ایراد دستگاه
          </strong>

          <span
            style={{
              fontSize: "14px",
            }}
          >
            {record.problem}
          </span>
        </div>

        {/* Details */}

        <Link
          to={`/request-details/${record.id}`}
          className="btn w-100 rounded-pill"
          style={{
            height: "50px",

            color: "#6389c8",

            border:
              "1px solid #6389c8",

            background: "#fff",

            transition:
              "all .25s ease",
          }}
        >
          دیدن جزئیات
        </Link>
      </div>
    );
  };

  // =========================================================
  // Cards
  // بدون Header
  // =========================================================

  renderCards = () => {
    const { records } = this.props;

    if (!records.length) {
      return this.renderEmpty();
    }

    return (
      <div
        className="row g-3"
        style={{
          animation:
            "recordsFade .4s ease",
        }}
      >
        {records.map(
          (record, index) => (
            <div
              key={record.id}
              className="col-6"
            >
              {this.renderCard(
                record,
                index
              )}
            </div>
          )
        )}
      </div>
    );
  };

  // =========================================================
  // Empty
  // =========================================================

  renderEmpty = () => {
    return (
      <div
        className="text-center py-5 text-secondary"
        style={{
          animation:
            "recordsFade .35s ease",
        }}
      >
        موردی برای نمایش وجود ندارد.
      </div>
    );
  };

  // =========================================================
  // Render
  // =========================================================

  render() {
    const { viewMode } =
      this.props;

    return (
      <div className="mt-2">
        {viewMode === "list"
          ? this.renderList()
          : this.renderCards()}

        <style>
          {`
            @keyframes recordsFade {
              from {
                opacity: 0;
                transform: translateY(8px);
              }

              to {
                opacity: 1;
                transform: translateY(0);
              }
            }

            @keyframes cardFade {
              from {
                opacity: 0;
                transform: translateY(12px);
              }

              to {
                opacity: 1;
                transform: translateY(0);
              }
            }
          `}
        </style>
      </div>
    );
  }
}

export default RequestRecords;
